python3 -I - <<'EOF'
import json, itertools, re
from fractions import Fraction

def solvable(nums, target):
    ops = ['+','-','*','/']
    def rec(items):
        if len(items)==1:
            yield items[0]
            return
        for i in range(len(items)):
            for j in range(len(items)):
                if i==j: continue
                rest=[items[k] for k in range(len(items)) if k!=i and k!=j]
                for op in ops:
                    if op=='/' and items[j]==0: continue
                    if op=='+' and i>j: continue
                    if op=='*' and i>j: continue
                    yield from rec(rest+[ (op, items[i], items[j]) ])
    # simpler: recursive value sets
    from functools import lru_cache
    def vals(items):
        if len(items)==1:
            return {items[0]}
        out=set()
        for i in range(len(items)):
            for j in range(len(items)):
                if i==j: continue
                rest=tuple(items[k] for k in range(len(items)) if k not in (i,j))
                a=items[i]; b=items[j]
                for v in ((a+b),(a-b),(a*b)):
                    out |= vals(rest+(Fraction(v),))
                if b!=0:
                    out |= vals(rest+(Fraction(a)/Fraction(b),))
        return out
    tgt=Fraction(target)
    return tgt in vals(tuple(Fraction(x) for x in nums))

import glob
gt_seen=set()
for f in sorted(glob.glob('results/grpo_countdown/val_generations/*.jsonl')):
    for line in open(f):
        r=json.loads(line)
        gt_seen.add(r['gts'])
gt_list=sorted(gt_seen)
print('unique gts in val:', len(gt_list))
unsolv=0
for g in gt_list[:200]:
    d=json.loads(g)
    if not solvable(d['numbers'], d['target']): unsolv+=1
print('checked 200, unsolvable:', unsolv)
EOF

